1	// Starfall Bulwark — main loop, wave director, economy, events, blessing
2	// drafts, site protocol bridge, G debug hooks and the ?autotest=1 suite.
3	import * as THREE from '../vendor/three.module.min.js';
4	import { makeWorld } from './world.js';
5	import { makeFX } from './fx.js';
6	import { makeEnemy, ENEMY, AFFIX } from './enemies.js';
7	import { TOWERS, makeTower, bindCurve, sellValue } from './towers.js';
8	import { makeAudio } from './audio.js';
9	import { makeUI } from './ui.js';
10	import { keys, pressed, mouse, endFrame, debugPanel, initTouch } from './input.js';
11	import { glowTex } from './assets.js';
12	
13	const DT = 1 / 60, CORE_MAX = 20, START_ESS = 130, TOTAL_WAVES = 10;
14	const SPAWN_IV = { crawler: 1.0, runner: .7, wisp: 1.2, brute: 1.6, shaman: 1.8, colossus: 3 };
15	
16	const WAVES = [
17	  [['crawler', 6]],
18	  [['crawler', 8], ['runner', 3]],
19	  [['crawler', 6], ['runner', 4], ['brute', 1]],
20	  [['crawler', 10], ['wisp', 5]],
21	  [['runner', 6], ['brute', 3], ['shaman', 1]],
22	  [['crawler', 8], ['wisp', 6], ['shaman', 2]],
23	  [['runner', 12], ['brute', 4]],
24	  [['crawler', 8], ['runner', 6], ['brute', 3], ['shaman', 2]],
25	  [['wisp', 10], ['shaman', 4], ['brute', 3]],
26	  [['colossus', 1], ['crawler', 8]],
27	];
28	
29	const BLESSINGS = [
30	  { id: 'sharp', zh: '锋鸣', glyph: '➶', max: 4, desc: '弩箭塔伤害 +20%', apply: () => mods.ballistaDmg += .2 },
31	  { id: 'alloy', zh: '磐晶合金', glyph: '◈', max: 4, desc: '全塔伤害 +8%', apply: () => mods.allDmg += .08 },
32	  { id: 'lens', zh: '透镜阵列', glyph: '◎', max: 3, desc: '全塔射程 +10%', apply: () => mods.range += .1 },
33	  { id: 'chill', zh: '霜寒入髓', glyph: '❄', max: 3, desc: '减速效果 +12%', apply: () => mods.slow += .12 },
34	  { id: 'grid', zh: '导电晶格', glyph: '⚡', max: 2, desc: '连雷弹跳 +1', apply: () => mods.chain += 1 },
35	  { id: 'ember', zh: '燃熔余烬', glyph: '☀', max: 2, desc: '迫炮溅射 +20%', apply: () => mods.splash += .2 },
36	  { id: 'focus', zh: '聚星光焦', glyph: '✧', max: 3, desc: '棱镜光束伤害 +25%', apply: () => mods.prismDmg += .25 },
37	  { id: 'well', zh: '潮汐聚灵', glyph: '◍', max: 4, desc: '星尘获取 +15%', apply: () => mods.essence += .15 },
38	  { id: 'weave', zh: '核心重塑', glyph: '❖', max: 99, desc: '立刻修复星核 +4', apply: () => { coreHp = Math.min(CORE_MAX, coreHp + 4); world.setCoreFrac(coreHp / CORE_MAX); } },
39	  { id: 'cap', zh: '过载电容', glyph: '⟡', max: 4, desc: '全塔射速 +8%', apply: () => mods.rate += .08 },
40	];
41	
42	const EVENTS = {
43	  tide:    { zh: '精 华 潮', sub: '本波击杀星尘翻倍', deep: false, apply: () => rewardMult = 2, revert: () => rewardMult = 1 },
44	  meteor:  { zh: '星 陨', sub: '陨石将坠入战场', deep: false, apply: () => { meteorQ = [3, 7, 11]; }, revert: () => meteorQ = [] },
45	  fog:     { zh: '迷 雾', sub: '本波全塔射程 -20%', deep: false, apply: () => fogWave = true, revert: () => fogWave = false },
46	  over:    { zh: '超 频', sub: '开波 18 秒射速 +45%', deep: false, apply: () => overchargeT = 18, revert: () => overchargeT = 0 },
47	  swarm:   { zh: '虫 潮', sub: '本波敌群 +30%', deep: false, apply: () => swarmMult = 1.3, revert: () => swarmMult = 1 },
48	  emp:     { zh: '磁 暴', sub: '随机哨塔将三次停机 4 秒', deep: true, apply: () => { empQ = [2, 10, 18]; }, revert: () => empQ = [] },
49	  corrode: { zh: '晶 蚀', sub: '本波敌群护甲 +3', deep: true, apply: () => waveArmor += 3, revert: () => waveArmor -= 3 },
50	  frenzy:  { zh: '狂 潮', sub: '本波敌群移速 +30%', deep: true, apply: () => waveSpd += .3, revert: () => waveSpd -= .3 },
51	};
52	
53	// --- state ---
54	let mode = 'title';                 // title | build | combat | draft | over | win
55	let wave = 0, wavesCleared = 0, endless = false;
56	let essence = START_ESS, coreHp = CORE_MAX;
57	let towers = [], enemies = [], spawnQ = [], meteorQ = [];
58	let speed = 1, paused = false, callT = 0, combatT = 0, overchargeT = 0;
59	let rewardMult = 1, fogWave = false, swarmMult = 1, lastEvent = '';
60	let waveArmor = 0, waveSpd = 0, empQ = [];
61	let qCd = 0, eCd = 0, rCd = 0, lastCycle = 0;
62	let noAuto = false;                 // autotest guard: build countdown never auto-calls
63	let selPad = -1, selTower = null;
64	let best = 0, newBest = false, nanFlag = false;
65	let mods, counts, reportTarget = null;
66	let reports = [];
67	const G = { err: [] }; window.__G = G;
68	
69	try { best = parseInt(localStorage.getItem('sfb.best') || '0') || 0; } catch (e) { best = 0; }
70	function saveBest() {
71	  const w = endless ? wave : Math.max(wavesCleared, wave);
72	  if (w > best) { best = w; newBest = true; try { localStorage.setItem('sfb.best', String(best)); } catch (e) { } }
73	}
74	
75	function resetState(toEndless = false) {
76	  wave = toEndless ? TOTAL_WAVES : 0;
77	  endless = toEndless; wavesCleared = 0;
78	  essence = START_ESS; coreHp = CORE_MAX;
79	  towers.forEach(t => t.dispose(world.scene)); towers = [];
80	  enemies.forEach(e => e.dispose(world.scene)); enemies = [];
81	  spawnQ = []; meteorQ = []; empQ = []; starfallQ = [];
82	  speed = 1; paused = false; callT = 0; combatT = 0; overchargeT = 0;
83	  rewardMult = 1; fogWave = false; swarmMult = 1; lastEvent = '';
84	  waveArmor = 0; waveSpd = 0; qCd = 0; eCd = 0; rCd = 0; lastCycle = 0;
85	  selPad = -1; selTower = null; newBest = false; nanFlag = false;
86	  mods = { ballistaDmg: 1, allDmg: 1, range: 1, rate: 1, slow: 0, chain: 0, splash: 1, prismDmg: 1, essence: 1 };
87	  counts = {};
88	  world.pads.forEach(p => { p.tower = null; p.glow.material.opacity = 0; });
89	  fx.clear(); ui.hideDraft(); ui.hideEnd(); ui.towerPanel(null); ui.boss(null);
90	  ui.speed(1); ui.pause(false); ui.callBtn(false); world.setCoreFrac(1);
91	}
92	
93	// --- boot ---
94	const world = makeWorld(document.getElementById('gl'));
95	bindCurve(world);
96	const fx = makeFX(world.scene);
97	const glowT = glowTex();
