1	// Orchard Fusion 果园大合成 — Suika-like merge puzzle.
2	// guizang-game-skill methodology, third series #1. Structure mirrors
3	// starfall-bulwark: fixed-step loop, G debug hooks, ?autotest=1 suite,
4	// site report bridge, WebAudio synth audio.
5	
6	import { FRUITS, SCORES, pickSpawnTier, makeSprites, drawSprite } from './fruits.js';
7	const MAX_TIER = FRUITS.length - 1;   // watermelon; top tier never merges further
8	import { makePhysics } from './physics.js';
9	import { makeAudio } from './audio.js';
10	import { makeUI } from './ui.js';
11	
12	// ==================== constants / layout ====================
13	const W = 540, H = 840;               // logical canvas size
14	const JAR = { left: 40, right: 500, floor: 800, top: 110 };
15	const DANGER_Y = 205;                 // settled fruit above this line for 2s = lose
16	const SPAWN_Y = 148;                  // aim fruit hover height
17	const COOLDOWN = 0.45;                // s between drops
18	const DANGER_TIME = 2.0;              // s above line to lose
19	const COMBO_CAP = 5;                  // chain multiplier cap
20	
21	// ==================== state ====================
22	let mode = 'title';                   // title | play | over
23	let paused = false, noAuto = false;
24	let score = 0, best = 0, maxTier = -1, totalMerges = 0;
25	try { best = parseInt(localStorage.getItem('orf.best') || '0') || 0; } catch (e) { }
26	let muted = false;
27	try { muted = localStorage.getItem('orf.mute') === '1'; } catch (e) { }
28	
29	const bodies = [];
30	const parts = [];                     // particles
31	const floats = [];                    // score floaters
32	let comboChain = 0;                   // merges within current drop chain
33	let cooldown = 0, curTier = -1, nextTier = -1, swapped = false;
34	let dangerT = 0, warnAcc = 0, hitstop = 0, shakeT = 0, shakeAmp = 0, flashT = 0;
35	let aimX = W / 2, holding = false;
36	let lastProgressT = 0, playT = 0;
37	
38	const rng = () => Math.random();
39	const phys = makePhysics({ left: JAR.left, right: JAR.right, floor: JAR.floor });
40	const audio = makeAudio();
41	const AUTOTEST = new URLSearchParams(location.search).has('autotest');
42	
43	// ==================== canvas ====================
44	const cv = document.getElementById('gl');
45	const ctx = cv.getContext('2d');
46	let viewScale = 1, viewOX = 0, viewOY = 0, DPR = 1;
47	
48	function resize() {
49	  DPR = Math.min(2, window.devicePixelRatio || 1);
50	  cv.width = Math.round(innerWidth * DPR); cv.height = Math.round(innerHeight * DPR);
51	  viewScale = Math.min(innerWidth / W, innerHeight / H);
52	  viewOX = (innerWidth - W * viewScale) / 2;
53	  viewOY = (innerHeight - H * viewScale) / 2;
54	}
55	addEventListener('resize', resize); resize();
56	makeSprites(Math.min(2, Math.max(1.5, DPR)));
57	
58	// static jar layer (pre-rendered once)
59	const bgCv = document.createElement('canvas');
60	bgCv.width = W * 2; bgCv.height = H * 2;
61	{
62	  const c = bgCv.getContext('2d'); c.scale(2, 2);
63	  const g = c.createLinearGradient(0, 0, 0, H);
64	  g.addColorStop(0, '#3a2a16'); g.addColorStop(.5, '#2b1d12'); g.addColorStop(1, '#1c1208');
65	  c.fillStyle = g; c.fillRect(0, 0, W, H);
66	  for (let i = 0; i < 40; i++) {
67	    c.fillStyle = `rgba(255,200,120,${.03 + Math.random() * .04})`;
68	    c.beginPath(); c.arc(Math.random() * W, Math.random() * H, 1.5 + Math.random() * 2.5, 0, 7); c.fill();
69	  }
70	  const ig = c.createLinearGradient(0, JAR.top, 0, JAR.floor);
71	  ig.addColorStop(0, 'rgba(255,232,190,.10)'); ig.addColorStop(1, 'rgba(255,214,150,.04)');
72	  c.fillStyle = ig; c.fillRect(JAR.left, JAR.top, JAR.right - JAR.left, JAR.floor - JAR.top);
73	  c.fillStyle = '#6e4a24'; c.fillRect(JAR.left - 26, JAR.top - 6, 26, JAR.floor - JAR.top + 12);
74	  c.fillStyle = '#5c3d1c'; c.fillRect(JAR.right, JAR.top - 6, 26, JAR.floor - JAR.top + 12);
75	  c.fillStyle = '#7c5628'; c.fillRect(JAR.left - 26, JAR.floor, JAR.right - JAR.left + 52, 30);
76	  c.strokeStyle = 'rgba(0,0,0,.25)'; c.lineWidth = 2;
77	  for (const x of [JAR.left - 13, JAR.right + 13]) { c.beginPath(); c.moveTo(x, JAR.top - 6); c.lineTo(x, JAR.floor + 30); c.stroke(); }
78	  c.strokeStyle = 'rgba(255,220,160,.15)';
79	  c.beginPath(); c.moveTo(JAR.left, JAR.top - 6); c.lineTo(JAR.left, JAR.floor); c.stroke();
80	  c.beginPath(); c.moveTo(JAR.right, JAR.top - 6); c.lineTo(JAR.right, JAR.floor); c.stroke();
81	}
82	
83	// ==================== UI ====================
84	const ui = makeUI({
85	  onStart: () => { audio.ensure(); audio.sfx.ui(); startGame(); },
86	  onRestart: () => { audio.sfx.ui(); startGame(); },
87	  onBackTitle: () => { audio.sfx.ui(); toTitle(); },
88	  onSwap: () => { audio.sfx.ui(); doSwap(); },
89	  onMute: () => toggleMute(),
90	  onPause: () => { audio.sfx.ui(); togglePause(); },
91	});
92	ui.setBest(best);
93	ui.showTitle(true);
94	ui.setMutedIcon(muted);
95	audio.setMuted(muted);
96	
97	// ==================== protocol bridge ====================
98	let reportTarget = null;
99	const reports = [];
100	function report(kind, payload = {}) {
101	  const frame = { kind, ...payload };
102	  reports.push(frame);
103	  try {
104	    if (reportTarget) reportTarget(frame);
105	    else if (window.parent !== window) window.parent.postMessage({ source: 'lightgame', type: 'lightgame:report', payload: frame }, '*');
106	  } catch (e) { }
107	}
108	report('ready', { game: 'orchard-fusion' });
109	
110	// ==================== game flow ====================
111	function resetPlay() {
112	  bodies.length = 0; parts.length = 0; floats.length = 0;
113	  score = 0; maxTier = -1; totalMerges = 0; comboChain = 0;
114	  cooldown = 0; dangerT = 0; hitstop = 0; shakeT = 0; flashT = 0;
115	  curTier = pickSpawnTier(rng); nextTier = pickSpawnTier(rng);
116	  swapped = false; playT = 0; lastProgressT = 0;
117	  ui.setScore(0); ui.drawNext(nextTier, FRUITS[nextTier].r * .5, drawSprite);
118	}
119	function startGame() {
120	  resetPlay();
121	  mode = 'play'; paused = false;
122	  ui.showTitle(false); ui.showEnd(false); ui.setPausedIcon(false);
123	  ui.el.banner.classList.remove('show');
124	  if (!audio.hasCtx() && !AUTOTEST) audio.ensure();   // autotest: stay ctx-less & silent
125	}
126	function toTitle() {
127	  mode = 'title'; paused = false;
128	  ui.showTitle(true); ui.showEnd(false);
129	  ui.setBest(best);
130	}
131	function togglePause() {
132	  if (mode !== 'play') return;
133	  paused = !paused;
134	  ui.setPausedIcon(paused);
135	  if (paused) { audio.stop(); ui.showBanner('已暂停', '按 P 或点按继续', 999999); }
136	  else { ui.el.banner.classList.remove('show'); }
137	}
138	function toggleMute() {
139	  muted = !muted;
140	  audio.setMuted(muted);
141	  ui.setMutedIcon(muted);
142	  try { localStorage.setItem('orf.mute', muted ? '1' : '0'); } catch (e) { }
143	}
144	function doSwap() {
145	  if (mode !== 'play' || paused || swapped || cooldown > 0) return;
146	  const t = curTier; curTier = nextTier; nextTier = t;
147	  swapped = true;
148	  ui.drawNext(nextTier, FRUITS[nextTier].r * .5, drawSprite);
149	  audio.sfx.swap();
150	}
151	
152	function spawnBody(tier, x, y, vx = 0, vy = 0) {
153	  const f = FRUITS[tier];
154	  const b = {
155	    tier, x: Math.max(JAR.left + f.r, Math.min(JAR.right - f.r, x)),
156	    y: Math.min(y, JAR.floor - f.r),      // merged fruit is bigger than parents: keep above floor
157	    vx, vy, r: f.r, rot: 0, hit: false, dead: false, born: 0,
158	  };
159	  bodies.push(b);
160	  return b;
161	}
162	
163	function dropFruit(x, force = false) {
164	  if (mode !== 'play' || paused) return false;
165	  if (!force && cooldown > 0) return false;
166	  if (curTier < 0) return false;
167	  spawnBody(curTier, x, SPAWN_Y, 0, 60);
168	  audio.sfx.drop(curTier);
169	  cooldown = COOLDOWN;
170	  comboChain = 0;                      // new drop starts a new chain
171	  swapped = false;
172	  curTier = nextTier;
173	  nextTier = pickSpawnTier(rng);
174	  ui.drawNext(nextTier, FRUITS[nextTier].r * .5, drawSprite);
175	  return true;
176	}
177	
178	function addScore(gain, x, y, comboN) {
179	  score += gain;
180	  ui.setScore(score);
181	  if (x || y) floats.push({ x, y, text: comboN > 1 ? `+${gain} ×${comboN}` : `+${gain}`, life: 1, color: comboN > 1 ? '#ffd77a' : '#fff2d8', size: comboN > 1 ? 24 + comboN * 2 : 20 });
182	  if (playT - lastProgressT > 3) {     // throttled milestone report
183	    lastProgressT = playT;
184	    report('progress', { score, progress: maxTier + 1 });
185	  }
186	}
187	
188	function mergePair(a, b) {
189	  const nt = a.tier + 1;
190	  const nx = (a.x * a.r + b.x * b.r) / (a.r + b.r);
191	  const ny = (a.y * a.r + b.y * b.r) / (a.r + b.r);
192	  const f = FRUITS[nt];
193	  a.dead = b.dead = true;
194	  comboChain++;
195	  const mult = Math.min(comboChain, COMBO_CAP);
196	  const gain = SCORES[nt] * mult;
197	  const nb = spawnBody(nt, nx, ny, (a.vx + b.vx) * .3, (a.vy + b.vy) * .3 - 40);
198	  if (nt > maxTier) maxTier = nt;
199	  totalMerges++;
200	  addScore(gain, nx, ny - f.r - 6, mult);
201	
202	  for (let i = 0; i < 10 + nt * 2; i++) {
203	    const a2 = Math.random() * Math.PI * 2, sp = 80 + Math.random() * (120 + nt * 30);
204	    parts.push({ x: nx, y: ny, vx: Math.cos(a2) * sp, vy: Math.sin(a2) * sp - 80, life: .5 + Math.random() * .3, max: .8, color: f.color, size: 3 + Math.random() * 5, grav: 900 });
205	  }
206	  audio.sfx.merge(nt, mult);
207	  if (nt >= 6) { shakeT = .22 + nt * .015; shakeAmp = 3 + nt * .5; }
208	  if (nt >= 7) hitstop = Math.max(hitstop, .07);
209	  if (mult >= 3 && comboChain <= COMBO_CAP) { audio.sfx.comboUp(mult); ui.showBanner(`连击 ×${mult}！`, '连续合成加成', 900); }
210	  if (nt >= 9) audio.sfx.bigMerge();
211	
212	  // watermelon celebration: fireworks + clear small fruits with bonus
213	  if (nt === 10) {
214	    audio.sfx.firework(); flashT = .35; shakeT = .5; shakeAmp = 8;
215	    ui.showBanner('西瓜诞生！', '全场庆典 · 小水果转化为分数', 2200);
216	    for (let i = 0; i < 70; i++) {
217	      const a2 = Math.random() * Math.PI * 2, sp = 120 + Math.random() * 380;
218	      const cols = ['#ffd77a', '#ff8a5c', '#9a5cd0', '#6fe8d8', '#f25767'];
219	      parts.push({ x: nx, y: ny, vx: Math.cos(a2) * sp, vy: Math.sin(a2) * sp, life: .9 + Math.random() * .6, max: 1.5, color: cols[i % cols.length], size: 3 + Math.random() * 4, grav: 500 });
220	    }
221	    let bonus = 0;
222	    for (const b of bodies) if (!b.dead && b.tier <= 1) { b.dead = true; bonus += SCORES[b.tier] * 2; }
223	    if (bonus > 0) { score += bonus; ui.setScore(score); floats.push({ x: nx, y: ny + 40, text: `庆典 +${bonus}`, life: 1.2, color: '#ffe9a8', size: 26 }); }
224	    report('event', { tag: 'watermelon', score });
225	  }
226	  return nb;
227	}
228	
229	function processMerges() {
230	  let guard = 0;
231	  while (guard++ < 24) {
232	    const pair = phys.findMerge(bodies, MAX_TIER);
233	    if (!pair) break;
234	    mergePair(pair[0], pair[1]);
235	    for (let i = bodies.length - 1; i >= 0; i--) if (bodies[i].dead) bodies.splice(i, 1);
236	  }
237	}
238	
239	function checkDanger(dt) {
240	  if (noAuto || mode !== 'play') return;
241	  let above = false;
242	  for (const b of bodies) {
243	    const settled = Math.abs(b.vx) + Math.abs(b.vy) < 40;
244	    if (settled && b.y - b.r * .6 < DANGER_Y) { above = true; break; }
245	  }
246	  if (above) {
247	    dangerT += dt;
248	    warnAcc += dt;
249	    if (warnAcc > .5) { warnAcc = 0; audio.sfx.warn(); }
250	    if (dangerT >= DANGER_TIME) gameOver();
251	  } else {
252	    dangerT = Math.max(0, dangerT - dt * 1.6);
253	    warnAcc = 0;
254	  }
255	}
256	
257	function gameOver() {
258	  if (mode !== 'play') return;
259	  mode = 'over';
260	  audio.sfx.lose();
261	  audio.stop();
262	  const isNew = score > best;
263	  if (isNew) { best = score; try { localStorage.setItem('orf.best', String(best)); } catch (e) { } }
264	  ui.setBest(best);
265	  const fname = maxTier >= 0 ? `${FRUITS[maxTier].name}${maxTier === 10 ? '🍉' : ''}` : '—';
266	  ui.setEnd(isNew ? '新纪录！' : '果园丰收',
267	    `得分 ${score}${isNew ? '  ⭐ 新纪录' : `\n纪录 ${best}`}\n最大水果 ${fname}\n合成 ${totalMerges} 次`);
268	  ui.showEnd(true);
269	  report('gameOver', { score, progress: maxTier + 1 });
270	}
271	
272	// ==================== update / frame ====================
273	function update(dt) {
274	  playT += dt;
275	  if (cooldown > 0) cooldown = Math.max(0, cooldown - dt);
276	  if (hitstop > 0) { hitstop -= dt; return; }        // brief freeze on big merges
277	
278	  phys.step(bodies, dt);
279	  processMerges();
280	  checkDanger(dt);
281	
282	  for (const b of bodies) { b.rot += (b.vx / Math.max(40, b.r)) * dt; b.born += dt; }
283	
284	  for (let i = parts.length - 1; i >= 0; i--) {
285	    const p = parts[i];
286	    p.life -= dt; if (p.life <= 0) { parts.splice(i, 1); continue; }
287	    p.vy += (p.grav || 0) * dt; p.x += p.vx * dt; p.y += p.vy * dt;
288	  }
289	  for (let i = floats.length - 1; i >= 0; i--) {
290	    const fl = floats[i];
291	    fl.life -= dt * 1.1; fl.y -= 34 * dt;
292	    if (fl.life <= 0) floats.splice(i, 1);
293	  }
294	  if (shakeT > 0) shakeT -= dt;
295	  if (flashT > 0) flashT -= dt;
296	
297	  let nearTop = false;
298	  for (const b of bodies) if (b.y - b.r < DANGER_Y + 90) { nearTop = true; break; }
299	  audio.state(nearTop ? 'danger' : 'calm');
300	  audio.update();
301	}
302	
303	// ==================== render ====================
304	function render() {
305	  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
306	  ctx.clearRect(0, 0, cv.width, cv.height);
307	  ctx.save();
308	  ctx.translate(viewOX, viewOY); ctx.scale(viewScale, viewScale);
309	  const shx = shakeT > 0 ? (Math.random() * 2 - 1) * shakeAmp * shakeT * 5 : 0;
310	  const shy = shakeT > 0 ? (Math.random() * 2 - 1) * shakeAmp * shakeT * 5 : 0;
311	  ctx.translate(shx, shy);
312	
313	  ctx.drawImage(bgCv, 0, 0, W, H);
314	
315	  const pulse = dangerT > 0 ? .5 + .5 * Math.sin(playT * 14) : 0;
316	  ctx.strokeStyle = `rgba(255,70,60,${.45 + pulse * .5})`;
317	  ctx.lineWidth = 2.5; ctx.setLineDash([10, 8]);
318	  ctx.beginPath(); ctx.moveTo(JAR.left, DANGER_Y); ctx.lineTo(JAR.right, DANGER_Y); ctx.stroke();
319	  ctx.setLineDash([]);
320	  if (dangerT > 0) {
321	    ctx.fillStyle = `rgba(255,60,50,${.05 + pulse * .1})`;
322	    ctx.fillRect(JAR.left, JAR.top, JAR.right - JAR.left, DANGER_Y - JAR.top);
323	  }
324	
325	  for (const b of bodies) drawSprite(ctx, b.tier, b.x, b.y, b.r, b.rot);
326	
327	  if (mode === 'play' && !paused && cooldown <= 0 && curTier >= 0) {
328	    const r = FRUITS[curTier].r;
329	    const bob = Math.sin(playT * 3) * 3;
330	    ctx.strokeStyle = 'rgba(255,220,160,.25)'; ctx.lineWidth = 2; ctx.setLineDash([4, 9]);
331	    ctx.beginPath(); ctx.moveTo(aimX, SPAWN_Y + r + 6); ctx.lineTo(aimX, JAR.floor - 4); ctx.stroke();
332	    ctx.setLineDash([]);
333	    drawSprite(ctx, curTier, aimX, SPAWN_Y + bob, r, 0, .96);
334	  }
335	
336	  for (const p of parts) {
337	    ctx.globalAlpha = Math.max(0, p.life / p.max);
338	    ctx.fillStyle = p.color;
339	    ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2); ctx.fill();
340	  }
341	  ctx.globalAlpha = 1;
342	
343	  ctx.textAlign = 'center';
344	  for (const fl of floats) {
345	    ctx.globalAlpha = Math.min(1, fl.life * 1.6);
346	    ctx.font = `700 ${fl.size}px "Microsoft YaHei",sans-serif`;
347	    ctx.fillStyle = fl.color;
348	    ctx.strokeStyle = 'rgba(60,30,5,.7)'; ctx.lineWidth = 3;
349	    ctx.strokeText(fl.text, fl.x, fl.y); ctx.fillText(fl.text, fl.x, fl.y);
350	  }
351	  ctx.globalAlpha = 1;
352	
353	  if (flashT > 0) {
354	    ctx.fillStyle = `rgba(255,240,200,${flashT * .9})`;
355	    ctx.fillRect(0, 0, W, H);
356	  }
357	  ctx.restore();
358	}
359	
360	// ==================== main loop ====================
361	let last = performance.now(), acc = 0;
362	function tick(now) {
363	  requestAnimationFrame(tick);
364	  let dt = (now - last) / 1000; last = now;
365	  if (document.hidden) return;
366	  handleKeys();   // consume pressed keys in the REAL loop too (was debug-only — keyboard was dead for players)
367	  dt = Math.min(dt, 1 / 30);
368	  if (mode === 'play' && !paused) {
369	    acc += dt;
370	    while (acc >= 1 / 60) { update(1 / 60); acc -= 1 / 60; }
371	  }
372	  render();
373	}
374	requestAnimationFrame(tick);
375	
376	// ==================== input ====================
377	const pressed = new Set();
378	addEventListener('keydown', (e) => {
379	  if (e.isComposing || e.keyCode === 229) return;
380	  if (e.metaKey || e.altKey || e.ctrlKey) return;
381	  if (!e.repeat) pressed.add(e.code);
382	  if (e.code === 'Space' || e.code === 'Tab') e.preventDefault();
383	});
384	addEventListener('blur', () => pressed.clear());
385	document.addEventListener('visibilitychange', () => pressed.clear());
386	
387	function handleKeys() {
388	  for (const code of pressed) {
389	    if (code === 'KeyP') togglePause();
390	    else if (code === 'KeyM') toggleMute();
391	    else if (code === 'KeyX') doSwap();
392	    else if (code === 'Enter') {
393	      if (mode === 'title' || mode === 'over') startGame();
394	    }
395	  }
396	  pressed.clear();
397	}
398	
399	cv.addEventListener('pointerdown', (e) => {
400	  if (mode !== 'play') return;
401	  audio.ensure();
402	  holding = true;
403	  aimX = toLogicalX(e.clientX);
404	  if (cv.setPointerCapture) { try { cv.setPointerCapture(e.pointerId); } catch (err) { } }
405	});
406	cv.addEventListener('pointermove', (e) => {
407	  if (mode !== 'play') return;
408	  if (!holding && e.pointerType !== 'mouse') return;
409	  aimX = toLogicalX(e.clientX);
410	});
411	cv.addEventListener('pointerup', (e) => {
412	  if (mode !== 'play') return;
413	  const x = toLogicalX(e.clientX);
414	  aimX = x; holding = false;
415	  dropFruit(x);
416	});
417	function toLogicalX(cx) {
418	  return Math.max(JAR.left + 10, Math.min(JAR.right - 10, (cx - viewOX) / viewScale));
419	}
420	
421	// ==================== G debug hooks ====================
422	const G = {
423	  err: window.__BOOTERR,
424	  W: 540, H: 840, JAR, DANGER_Y,
425	  step: (n = 60, dt = 1 / 60) => { for (let i = 0; i < n; i++) { handleKeys(); if (mode === 'play' && !paused) update(dt); render(); } },
426	  upd: (n = 30, dt = 1 / 60) => { for (let i = 0; i < n; i++) { handleKeys(); if (mode === 'play' && !paused) update(dt); } },
427	  press: (...codes) => codes.forEach(c => pressed.add(c)),
428	  dropAt: (x, force = false) => dropFruit(x, force),
429	  spawnTier: (t, x, y) => spawnBody(t, x, y),
430	  setNoAuto: (v) => { noAuto = !!v; },
431	  setReportTarget: (fn) => { reportTarget = fn; },
432	  setScore: (v) => { score = v | 0; ui.setScore(score); lastProgressT = -99; },
433	  setNextTier: (t) => { if (t >= 0 && t < FRUITS.length) { nextTier = t; ui.drawNext(nextTier, FRUITS[nextTier].r * .5, drawSprite); } },
434	  state: () => ({ mode, paused, score, best, maxTier, totalMerges, comboChain, dangerT, cooldown: +cooldown.toFixed(3), curTier, nextTier, swapped, fruits: bodies.length }),
435	  fx: () => ({ parts: parts.length, floats: floats.length }),
436	  audio,
437	  bodies,
438	  forceGameOver: () => gameOver(),
439	  startGame,
440	};
441	window.__G = G;
442	window.addEventListener('error', e => { if (G.err) G.err.push(String(e.message || e)); });
443	
444	// ==================== autotest suite ====================
445	const nap = () => new Promise(r => { const mc = new MessageChannel(); mc.port1.onmessage = () => r(); mc.port2.postMessage(0); });
446	
447	async function autotest() {
448	  const results = [];
449	  try { await autotestInner(results); }
450	  catch (err) {
451	    window.__TEST_ERR = String(err && err.stack || err);
452	    console.error('[autotest] crashed:', window.__TEST_ERR);
453	    window.__TEST = { pass: results.filter(r => r.ok).length, fail: 99, total: results.length + 99, results, done: true, crashed: true };
454	  }
455	  return;
456	  async function autotestInner(results) {
457	  const assert = (id, ok, name) => { results.push({ id, ok: !!ok, name }); if (!ok) console.warn(`[T${id}] FAIL ${name}`); };
458	  const S = () => G.state();
459	  audio.setMuted(true);
460	  const savedBest = best;
461	  const frames = [];
462	  G.setReportTarget(f => frames.push(f));
463	
464	  assert(1, G.err.length === 0, '启动零报错');
465	
466	  // -- T2-T4: drop physics basics
467	  startGame();
468	  G.setNoAuto(true);
469	  const before = S().fruits;
470	  const dropped = G.dropAt(W / 2, true);
471	  assert(2, dropped && S().fruits === before + 1, 'dropFruit 增加一个水果');
472	  const y0 = bodies[bodies.length - 1].y;
473	  G.upd(30);
474	  const b0 = bodies[0];
475	  assert(3, b0 && b0.y > y0 && !isNaN(b0.y), '水果下落且无 NaN');
476	  G.upd(120);
477	  assert(4, b0.y + b0.r <= JAR.floor + .5 && b0.x - b0.r >= JAR.left - .5 && b0.x + b0.r <= JAR.right + .5, '水果停在罐内边界内');
478	
479	  // -- T5/T6: same-tier merge + score
480	  startGame();
481	  const s0 = S().score;
482	  G.spawnTier(2, 200, 500); G.spawnTier(2, 232, 500);
483	  G.upd(30);
484	  assert(5, !!bodies.find(b => b.tier === 3), '同 tier 碰撞合成出下一级');
485	  assert(6, S().score >= s0 + SCORES[3], '合成得等级分');
486	
487	  // -- T7/T8: simultaneous double merge → combo ×1/×2
488	  startGame();
489	  G.spawnTier(3, 160, 400); G.spawnTier(3, 192, 400);   // pair 1
490	  G.spawnTier(3, 120, 700); G.spawnTier(3, 152, 700);   // pair 2 (both in-bounds)
491	  const sB = S().score;
492	  G.upd(2);                                              // both pairs merge in one pass
493	  const gainT = S().score - sB;
494	  assert(7, gainT === SCORES[4] * 1 + SCORES[4] * 2, '同帧双连锁按 ×1/×2 计分');
495	  assert(8, S().comboChain >= 2, '连锁 combo 计数 ≥2');
496	
497	  // -- T9: cooldown rejects rapid drop
498	  startGame();
499	  const n0 = S().fruits;
500	  G.dropAt(300, true);
501	  const rejected = G.dropAt(300);
502	  assert(9, rejected === false && S().fruits === n0 + 1, '冷却期内拒绝再次掉落');
503	
504	  // -- T10: restart resets state
505	  G.forceGameOver();
506	  startGame();
507	  const st = S();
508	  assert(10, st.score === 0 && st.fruits === 0 && st.mode === 'play' && st.totalMerges === 0, '重开一局状态复位');
509	
510	  // -- T11/T12: swap once per drop cycle
511	  startGame();
512	  const c0 = S().curTier, n1 = S().nextTier;
513	  G.press('KeyX'); G.upd(1);
514	  assert(11, S().curTier === n1 || c0 === n1, '交换当前与下一个');
515	  const c2 = S().curTier;
516	  G.press('KeyX'); G.upd(1);
517	  assert(12, S().curTier === c2, '同一投放周期内第二次交换被拒绝');
518	
519	  // -- T13/T14/T15: watermelon celebration
520	  startGame();
521	  G.spawnTier(0, 90, 760); G.spawnTier(1, 150, 700);
522	  const scoreWM = S().score;
523	  G.spawnTier(9, 300, 300); G.spawnTier(9, 345, 300);
524	  G.upd(30);
525	  assert(13, !!bodies.find(b => b.tier === 10), '两个甜瓜合成出西瓜');
526	  assert(14, bodies.filter(b => b.tier <= 1).length === 0, '西瓜庆典清除全部小水果');
527	  assert(15, S().score > scoreWM + SCORES[10], '西瓜庆典加分超过基础分');
528	
529	  // -- T16-T18: physics stability under load
530	  startGame();
531	  for (let i = 0; i < 60; i++) G.spawnTier(i % 6, JAR.left + 30 + Math.random() * (JAR.right - JAR.left - 60), 200 + Math.random() * 300);
532	  let nan = false, outside = false, exploded = false;
533	  for (let i = 0; i < 600; i++) {
534	    G.upd(1);
535	    for (const b of bodies) {
536	      if (isNaN(b.x) || isNaN(b.y) || isNaN(b.vx) || isNaN(b.vy)) nan = true;
537	      if (b.x - b.r < JAR.left - 2 || b.x + b.r > JAR.right + 2 || b.y + b.r > JAR.floor + 2) outside = true;
538	      if (Math.abs(b.vx) > 3300 || Math.abs(b.vy) > 3300) exploded = true;
539	    }
540	  }
541	  assert(16, !nan, '60 果 600 帧无 NaN');
542	  assert(17, !outside, '60 果 600 帧无出界');
543	  assert(18, !exploded, '速度钳制无爆炸');
544	
545	  // -- T19/T20: pause freezes physics
546	  startGame();
547	  G.spawnTier(3, W / 2, 300); G.upd(60);
548	  const py = bodies[0].y;
549	  G.press('KeyP'); G.upd(10);
550	  assert(19, Math.abs(bodies[0].y - py) < .001 && S().paused, '暂停冻结物理');
551	  G.press('KeyP'); G.upd(5);
552	  const resumed = !S().paused;
553	  G.dropAt(200, true); G.upd(15);
554	  const moved = bodies[bodies.length - 1].y > SPAWN_Y;
555	  assert(20, resumed && moved, '恢复运行且新水果继续下落');
556	
557	  // -- T21/T22: danger line lose path with real accumulation
558	  startGame();
559	  G.setNoAuto(false);
560	  for (let i = 0; i < 120; i++) {
561	    G.spawnTier(i % 7, 110 + Math.random() * 320, 190 + Math.random() * 380);
562	    if (i % 12 === 11) G.upd(20);
563	  }
564	  G.upd(90);
565	  let maxDanger = 0;
566	  for (let i = 0; i < 400 && S().mode === 'play'; i++) { G.upd(1); if (S().dangerT > maxDanger) maxDanger = S().dangerT; }
567	  assert(21, S().mode === 'over', '堆过警戒线 2 秒判负');
568	  assert(22, frames.some(f => f.kind === 'gameOver'), 'gameOver 上报帧');
569	
570	  // -- T23: grace — moving fruit above line does not lose
571	  startGame();
572	  const flyer = G.spawnTier(4, W / 2, 160);
573	  flyer.vy = -620;
574	  G.upd(50);
575	  assert(23, S().mode === 'play' && S().dangerT < .2, '运动水果越线有宽限不判负');
576	  G.setNoAuto(true);
577	
578	  // -- T24: best persistence (isolate from earlier runs' pollution)
579	  startGame();
580	  best = 0; try { localStorage.setItem('orf.best', '0'); } catch (e) { }
581	  G.setScore(1234);
582	  G.forceGameOver();
583	  const bestNow = parseInt(localStorage.getItem('orf.best') || '0') || 0;
584	  assert(24, bestNow === 1234 && S().best === 1234, '纪录写入 localStorage');
585	  try { localStorage.setItem('orf.best', String(savedBest)); } catch (e) { }
586	  best = savedBest;
587	
588	  // -- T25-T27: protocol frame sequence (module-level `reports` captures all frames)
589	  assert(25, reports[0] && reports[0].kind === 'ready', 'ready 上报帧为首帧');
590	  assert(26, frames.some(f => f.kind === 'progress') || frames.some(f => f.kind === 'event'), 'progress/event 上报帧存在');
591	  assert(27, frames[frames.length - 1] && frames[frames.length - 1].kind === 'gameOver', 'gameOver 为当前末帧');
592	
593	  // -- T28: UI DOM bindings
594	  assert(28, !!ui.el.mutebtn && !!ui.el.pausebtn && !!ui.el.nextbox && !!ui.el.start, '静音/暂停/交换/开始 UI 元素存在');
595	
596	  // -- T29-T31: audio synth
597	  audio.ensure();
598	  assert(29, audio.hasCtx(), 'AudioContext 可创建');
599	  audio.state('danger');
600	  assert(30, audio.state() === 'danger', '配乐状态切换 danger');
601	  audio.state('calm');
602	  assert(31, audio.isMuted() === true, '自测期间保持静音');
603	
604	  // -- T32/T33: full session fast-forward
605	  const errBefore = G.err.length;
606	  startGame();
607	  for (let i = 0; i < 240; i++) { G.dropAt(JAR.left + 20 + Math.random() * (JAR.right - JAR.left - 40), true); G.upd(3); }
608	  for (let i = 0; i < 200; i++) G.upd(2);
609	  let nan2 = false;
610	  for (const b of bodies) if (isNaN(b.x) || isNaN(b.y)) nan2 = true;
611	  assert(32, !nan2 && G.err.length === errBefore, '整局快进 240 投无 NaN 无新报错');
612	  if (S().mode === 'play') for (let i = 0; i < 30; i++) { G.spawnTier(7 + (i % 3), 110 + Math.random() * 320, 150 + Math.random() * 300); G.upd(5); }
613	  G.setNoAuto(false);
614	  for (let i = 0; i < 900 && S().mode === 'play'; i++) G.upd(1);
615	  assert(33, S().mode === 'over', '堆满后自然判负到结算');
616	
617	  // -- T34: back to title screen
618	  toTitle();
619	  assert(34, !ui.el.title.classList.contains('hide') && S().mode === 'title', '测完回到标题画面');
620	
621	  // restore the player's real best record (test sessions may have overwritten it)
622	  try { localStorage.setItem('orf.best', String(savedBest)); } catch (e) { }
623	  best = savedBest; ui.setBest(best);
624	
625	  const pass = results.filter(r => r.ok).length;
626	  window.__TEST = { pass, fail: results.length - pass, total: results.length, results, done: true };
627	  console.log(`[autotest] ${pass}/${results.length} passed`);
628	  }
629	}
630	
631	if (new URLSearchParams(location.search).get('autotest')) autotest();
