  held.delete(e.code);
  if (e.code === 'Space') releaseCharge();
});
addEventListener('blur', () => {
  held.clear(); touchL = touchR = false; touchCharge = false;
  charging = false; charge = 0;
});

// mouse / touch on the playfield: tap left/right half flips, tap launches
