];

export const LANE_BALL = { x: LANE_X, y: 840 };

export function makeBall(x, y, vx = 0, vy = 0) {
  return { x, y, vx, vy, r: BALL_R, inLane: false, age: 0, trail: [] };
}

export function inLane(b) { return b.x > 476 && b.x < 524 && b.y > 780; }

