  }
  const s=G.state();
  out.play={mode:s.mode,score:s.score,ballsLeft:s.ballsLeft,tasksDone:s.tasksDone,multiplier:s.multiplier,live:s.liveBalls,frames:flips,targetsLit:s.targetsLit,combo:s.combo,progress:s.progress};
